import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import EvidenceUpload from "@/components/EvidenceUpload";
import MediaSpecializedOperationsPanel from "@/components/MediaSpecializedOperationsPanel";
import SearchableMultiSelect from "@/components/SearchableMultiSelect";
import UrbanPointDetails from "./UrbanPointDetails";
import { useEffectivePermissions } from "@/hooks/useEffectivePermissions";
import { trpc } from "@/lib/trpc";
import { ArrowLeft, Building2, CalendarClock, ChevronRight, ExternalLink, FileImage, History, MapPin, Megaphone, Plus, RadioTower, RefreshCw, RotateCcw, SlidersHorizontal, Truck } from "lucide-react";
import { Children, FormEvent, isValidElement, ReactNode, useMemo, useState } from "react";
