type ChannelKind = "standard" | "external";
type PartnershipType = "paid" | "barter" | "mixed";
type MediaOperationCategory = "graphics" | "audio_video" | "leafleting" | "sound_car" | "influencers";
const operationCategoryMeta: Record<MediaOperationCategory, { title: string; description: string; channel: ChannelKind }> = {
  graphics: { title: "Mídia Urbana", description: "Planeje outdoors, painéis e demais superfícies urbanas com fornecedor, cobertura, vigência, evidências e debriefing.", channel: "standard" },
  audio_video: { title: "Mídia Tradicional", description: "Controle rádios, TVs, horários de veiculação, spots ativos, comprovações e debriefing por fornecedor.", channel: "standard" },
  leafleting: { title: "Panfletagem", description: "Organize a distribuição territorial vinculada a campanhas, promoções, planos, setores e evidências de execução.", channel: "external" },
  sound_car: { title: "Carro de Som", description: "Acompanhe fornecedores, spots, dias, horários, rotas, rodagem e evidências de cada ativação.", channel: "external" },
  influencers: { title: "Influencers", description: "Planeje os pontos e campanhas vinculados às parcerias com influenciadores, posts e comprovações.", channel: "standard" },
};
const emptyPoint = { supplierId: "", cityId: "", mediaTypeId: "", mediaVariationTypeId: "", serviceTypeId: "", name: "", operationCategory: "graphics" as MediaOperationCategory, replacementFrequency: "", address: "", coordinates: "" };
const emptyCampaign = { tradeCampaignId: "", name: "", startsOn: "", endsOn: "", partnershipType: "paid" as PartnershipType, estimatedCost: "", notes: "", campaignDetails: "", rescheduleReason: "", dailyRate: "", circulationDays: "", dailyRoute: "", audioBrief: "", vehicleOperation: "", airingSchedule: "", activeSpotId: "", materialFormat: "", materialQuantity: "", deadlineDays: "", deliveryInstructions: "" };
const emptyDebrief = { rating: "", resultAchieved: true, feedback: "" };
const campaignStatusLabel: Record<string, string> = { active: "Ativa", scheduled: "Agendada", completed: "Encerrada", cancelled: "Cancelada" };
const partnershipLabel: Record<PartnershipType, string> = { paid: "Pago", barter: "Permuta", mixed: "Misto" };

export function SelectField({ label, children, value, onChange, disabled, id, ...props }: React.ComponentProps<"select"> & { label: string }) {
  const options = Children.toArray(children).flatMap((child, index) => {
    if (!isValidElement<{ value?: string | number; children?: ReactNode }>(child)) return [];
    return [{ id: index + 1, value: String(child.props.value ?? ""), label: String(child.props.children ?? "") }];
  });
  const selected = options.find(option => option.value === String(value ?? ""));
  return <SearchableMultiSelect id={id ?? `media-select-${label.toLocaleLowerCase("pt-BR").replaceAll(/[^a-z0-9]+/g, "-")}`} label={label} disabled={disabled} options={options.map(({ id: optionId, label: optionLabel }) => ({ id: optionId, label: optionLabel }))} values={selected ? [selected.id] : []} onChange={values => {
    const option = options.find(item => item.id === values[0]);
    onChange?.({ target: { value: option?.value ?? "" } } as React.ChangeEvent<HTMLSelectElement>);
  }} maxSelections={1} placeholder={`Selecionar ${label.toLocaleLowerCase("pt-BR")}`} emptyMessage="Nenhuma opção disponível" />;
}

function MediaDetailPage({ mediaPointId }: { mediaPointId: number }) {
  const [, setLocation] = useLocation();
  const { can } = useEffectivePermissions();
  const canWrite = can("media.write");
  const detail = trpc.media.pointDetails.useQuery({ mediaPointId });
  const point = detail.data;
  return <main className="mx-auto max-w-6xl space-y-5">
    <Button type="button" variant="outline" onClick={() => setLocation("/midias")} className="border-border"><ArrowLeft className="mr-1.5 h-4 w-4" />Voltar para mídias</Button>
    <header className="rounded-2xl border border-border bg-card p-5 shadow-sm"><p className="text-[11px] font-semibold uppercase tracking-[0.14em] text-primary">Ficha operacional de mídia</p><h1 className="mt-1 font-display text-3xl font-semibold text-foreground">{point?.name ?? "Detalhes da mídia"}</h1><p className="mt-2 text-sm text-muted-foreground">Fornecedor, cobertura, ciclos, histórico e evidências do ponto selecionado.</p></header>
    {detail.isLoading ? <div className="grid h-48 place-items-center rounded-2xl border border-border bg-card text-sm text-muted-foreground">Carregando detalhes...</div> : point ? <div className="grid gap-5 lg:grid-cols-[.8fr_1.2fr]"><aside className="space-y-4"><article className="rounded-xl bg-secondary p-4"><div className="flex items-center gap-2 text-sm font-semibold text-foreground"><Building2 className="h-4 w-4 text-primary" />Cobertura e fornecedor</div><dl className="mt-4 space-y-3 text-sm"><div><dt className="text-xs text-muted-foreground">Fornecedor</dt><dd className="font-medium text-foreground">{point.supplierName}</dd></div><div><dt className="text-xs text-muted-foreground">Território</dt><dd className="font-medium text-foreground">{point.cityName} · {point.regionalName}</dd></div><div><dt className="text-xs text-muted-foreground">Tipo de mídia</dt><dd className="font-medium text-foreground">{point.mediaTypeName}{point.serviceTypeName ? ` · ${point.serviceTypeName}` : ""}</dd></div><div><dt className="text-xs text-muted-foreground">Localização</dt><dd className="font-medium text-foreground">{point.address || "Não informada"}</dd></div></dl></article><article className="rounded-xl border border-border bg-card p-4"><div className="flex items-center gap-2 text-sm font-semibold text-foreground"><History className="h-4 w-4 text-primary" />Histórico</div><div className="mt-3 space-y-3">{point.history.length ? point.history.map(entry => <div key={`${entry.scope}-${entry.id}`} className="border-l-2 border-primary/30 pl-3"><p className="text-xs font-medium text-foreground">{entry.action === "schedule" ? "Campanha agendada" : entry.action === "reschedule" ? "Campanha reagendada" : entry.action === "create" ? "Registro criado" : "Atualização registrada"}</p><p className="mt-0.5 text-[11px] text-muted-foreground">{new Date(entry.occurredAt).toLocaleString("pt-BR")}</p></div>) : <p className="text-xs text-muted-foreground">Ainda não há alterações registradas.</p>}</div></article></aside><section className="overflow-hidden rounded-xl border border-border bg-card"><div className="border-b border-border px-4 py-3"><p className="text-sm font-semibold text-foreground">Ciclos e comprovações</p><p className="mt-0.5 text-xs text-muted-foreground">Toda programação e alteração permanece no histórico deste ponto.</p></div><div className="divide-y divide-border">{point.campaigns.length ? point.campaigns.map(campaign => <article key={campaign.id} className="p-4"><div className="flex flex-wrap items-center gap-2"><p className="font-semibold text-foreground">{campaign.name}</p><Badge className="border-0 bg-secondary text-[10px] text-foreground">{campaignStatusLabel[campaign.status] ?? campaign.status}</Badge><Badge className="border-0 bg-primary/10 text-[10px] text-primary">{partnershipLabel[campaign.partnershipType as PartnershipType]}</Badge></div><p className="mt-1 text-xs text-muted-foreground">{new Date(`${campaign.startsOn}T12:00:00`).toLocaleDateString("pt-BR")} até {new Date(`${campaign.endsOn}T12:00:00`).toLocaleDateString("pt-BR")} · {Number(campaign.estimatedCost).toLocaleString("pt-BR", { style: "currency", currency: "BRL" })}</p>{campaign.campaignDetails && <p className="mt-2 text-xs leading-5 text-muted-foreground">{campaign.campaignDetails}</p>}{campaign.notes && <p className="mt-1 text-xs leading-5 text-muted-foreground">{campaign.notes}</p>}<div className="mt-3 flex flex-wrap gap-2">{campaign.evidences.map(evidence => <a key={evidence.id} href={evidence.url} target="_blank" rel="noreferrer" className="inline-flex items-center gap-1 rounded-md bg-secondary px-2 py-1 text-[11px] font-medium text-foreground hover:bg-primary/10"><ExternalLink className="h-3 w-3" />{evidence.originalName}</a>)}</div><div className="mt-3"><EvidenceUpload entityType="media_campaign" entityId={campaign.id} regionalId={point.regionalId} canWrite={canWrite} /></div></article>) : <p className="p-5 text-sm text-muted-foreground">Nenhuma campanha registrada para este ponto.</p>}</div></section></div> : <div className="rounded-2xl border border-border bg-card p-8 text-sm text-muted-foreground">Esta mídia não foi encontrada ou você não possui acesso a ela.</div>}
  </main>;
}

export default function MediaWorkspace({ initialChannel, initialCategory }: { initialChannel?: ChannelKind; initialCategory?: MediaOperationCategory }) {
  const [, setLocation] = useLocation();
  const [isDetailRoute, routeParams] = useRoute("/midias/:mediaPointId");
  const routeMediaPointId = isDetailRoute && routeParams?.mediaPointId ? Number(routeParams.mediaPointId) : null;
  const { can } = useEffectivePermissions();
  const canWrite = can("media.write");
  const utils = trpc.useUtils();
  const references = trpc.media.referenceData.useQuery();
  const tradeCampaigns = trpc.campaigns.list.useQuery();
  const categoryMeta = initialCategory ? operationCategoryMeta[initialCategory] : null;
  const [filters, setFilters] = useState({ regionalId: "", cityId: "", channelKind: initialChannel ?? categoryMeta?.channel ?? "", operationCategory: initialCategory ?? "", status: "", partnershipType: "" });
  const listInput = useMemo(() => ({ regionalId: filters.regionalId ? Number(filters.regionalId) : undefined, cityId: filters.cityId ? Number(filters.cityId) : undefined, channelKind: filters.channelKind ? filters.channelKind as ChannelKind : undefined, operationCategory: filters.operationCategory ? filters.operationCategory as MediaOperationCategory : undefined, status: filters.status ? filters.status as "active" | "scheduled" | "completed" | "cancelled" : undefined, partnershipType: filters.partnershipType ? filters.partnershipType as PartnershipType : undefined }), [filters]);
  const points = trpc.media.list.useQuery(listInput);
  const [showPointForm, setShowPointForm] = useState(false);
  const [showFilters, setShowFilters] = useState(!initialCategory);
  const [campaignPointId, setCampaignPointId] = useState<number | null>(null);
  const [rescheduleCampaignId, setRescheduleCampaignId] = useState<number | null>(null);
  const specializedData = trpc.media.listSpecializedData.useQuery(undefined, { enabled: initialCategory === "audio_video" || campaignPointId !== null });
  const [debriefCampaignId, setDebriefCampaignId] = useState<number | null>(null);
  const detailPointId = null;
  const setDetailPointId = (id: number | null) => { if (id) setLocation(`/midias/${id}`); };
  const [pointForm, setPointForm] = useState(emptyPoint);
  const [campaignForm, setCampaignForm] = useState(emptyCampaign);
  const [cityDistributions, setCityDistributions] = useState<Array<{ cityId: string; quantity: string; notes: string }>>([]);
  const [distributionDraft, setDistributionDraft] = useState({ cityId: "", quantity: "", notes: "" });
  const [debriefForm, setDebriefForm] = useState(emptyDebrief);
  const pointDetails = trpc.media.pointDetails.useQuery({ mediaPointId: detailPointId ?? 1 }, { enabled: detailPointId !== null });
  const invalidateMedia = () => { utils.media.list.invalidate(); utils.media.pointDetails.invalidate(); };
  const createPoint = trpc.media.createPoint.useMutation({ onSuccess: () => { toast.success("Ponto de mídia cadastrado."); invalidateMedia(); setShowPointForm(false); setPointForm(emptyPoint); }, onError: error => toast.error(error.message) });
  const createCampaign = trpc.media.createCampaign.useMutation({ onSuccess: result => { toast.success(result.status === "scheduled" ? "Mídia agendada com sucesso." : "Campanha criada com sucesso."); invalidateMedia(); setCampaignPointId(null); setCampaignForm(emptyCampaign); }, onError: error => toast.error(error.message) });
  const createConfiguredCampaign = trpc.media.createConfiguredCampaign.useMutation({ onSuccess: result => { toast.success(result.status === "scheduled" ? "Mídia agendada com configuração operacional." : "Campanha criada com configuração operacional."); invalidateMedia(); setCampaignPointId(null); setCampaignForm(emptyCampaign); setCityDistributions([]); }, onError: error => toast.error(error.message) });
  const renewCampaign = trpc.media.renewCampaign.useMutation({ onSuccess: () => { toast.success("Mídia reagendada e histórico preservado."); invalidateMedia(); setRescheduleCampaignId(null); setCampaignForm(emptyCampaign); }, onError: error => toast.error(error.message) });
  const saveDebrief = trpc.media.saveDebrief.useMutation({ onSuccess: () => { toast.success("Debriefing de mídia registrado."); invalidateMedia(); setDebriefCampaignId(null); setDebriefForm(emptyDebrief); }, onError: error => toast.error(error.message) });
  const submitPoint = (event: FormEvent) => { event.preventDefault(); const coordinates = pointForm.coordinates.split(/[,;\s]+/).filter(Boolean).map(Number); createPoint.mutate({ supplierId: Number(pointForm.supplierId), cityId: Number(pointForm.cityId), mediaTypeId: Number(pointForm.mediaTypeId), mediaVariationTypeId: null, serviceTypeId: pointForm.serviceTypeId ? Number(pointForm.serviceTypeId) : null, name: pointForm.name, operationCategory: pointForm.operationCategory, replacementFrequency: null, address: pointForm.address || undefined, latitude: coordinates.length === 2 ? coordinates[0] : null, longitude: coordinates.length === 2 ? coordinates[1] : null }); };
  const submitCampaign = (event: FormEvent) => { event.preventDefault(); const payload = { name: campaignForm.name, startsOn: campaignForm.startsOn, endsOn: campaignForm.endsOn, partnershipType: campaignForm.partnershipType, estimatedCost: Number(campaignForm.estimatedCost || 0), notes: campaignForm.notes || undefined, campaignDetails: campaignForm.campaignDetails || undefined }; if (rescheduleCampaignId) renewCampaign.mutate({ sourceCampaignId: rescheduleCampaignId, ...payload, rescheduleReason: campaignForm.rescheduleReason || undefined }); else if (campaignPointId) createConfiguredCampaign.mutate({ mediaPointId: campaignPointId, tradeCampaignId: campaignForm.tradeCampaignId ? Number(campaignForm.tradeCampaignId) : null, ...payload, campaignConfig: { dailyRate: campaignForm.dailyRate ? Number(campaignForm.dailyRate) : undefined, circulationDays: campaignForm.circulationDays ? Number(campaignForm.circulationDays) : undefined, dailyRoute: campaignForm.dailyRoute || undefined, audioBrief: campaignForm.audioBrief || undefined, vehicleOperation: campaignForm.vehicleOperation || undefined, airingSchedule: campaignForm.airingSchedule || undefined, activeSpotId: campaignForm.activeSpotId ? Number(campaignForm.activeSpotId) : undefined, materialFormat: campaignForm.materialFormat || undefined, materialQuantity: campaignForm.materialQuantity ? Number(campaignForm.materialQuantity) : undefined, deadlineDays: campaignForm.deadlineDays ? Number(campaignForm.deadlineDays) : undefined, deliveryInstructions: campaignForm.deliveryInstructions || undefined }, cityDistributions: cityDistributions.map(item => ({ cityId: Number(item.cityId), quantity: Number(item.quantity), notes: item.notes || undefined })) }); };
  const openSchedule = (pointId: number) => { setCampaignForm(emptyCampaign); setCityDistributions([]); setDistributionDraft({ cityId: "", quantity: "", notes: "" }); setRescheduleCampaignId(null); setCampaignPointId(pointId); };
  const openReschedule = (campaign: { id: number; name: string; partnershipType: string; estimatedCost: string | number; notes: string | null; campaignDetails: string | null }) => { setCampaignPointId(null); setRescheduleCampaignId(campaign.id); setCampaignForm({ ...emptyCampaign, name: campaign.name, partnershipType: campaign.partnershipType as PartnershipType, estimatedCost: String(campaign.estimatedCost), notes: campaign.notes ?? "", campaignDetails: campaign.campaignDetails ?? "" }); };
  const openDebrief = (campaign: { id: number; rating: number | null; resultAchieved: boolean | null; feedback: string | null }) => { setDebriefCampaignId(campaign.id); setDebriefForm({ rating: campaign.rating ? String(campaign.rating) : "", resultAchieved: campaign.resultAchieved ?? true, feedback: campaign.feedback ?? "" }); };
  const submitDebrief = (event: FormEvent) => { event.preventDefault(); if (debriefCampaignId) saveDebrief.mutate({ campaignId: debriefCampaignId, rating: Number(debriefForm.rating), resultAchieved: debriefForm.resultAchieved, feedback: debriefForm.feedback }); };
  const resetFilters = () => setFilters({ regionalId: "", cityId: "", channelKind: initialChannel ?? categoryMeta?.channel ?? "", operationCategory: initialCategory ?? "", status: "", partnershipType: "" });
  const scheduledPoint = useMemo(() => points.data?.find(point => point.id === campaignPointId) ?? null, [campaignPointId, points.data]);
  const scheduledServiceName = scheduledPoint?.serviceTypeName?.toLocaleLowerCase("pt-BR") ?? "";
  const needsAudioVideoConfig = scheduledPoint?.operationCategory === "audio_video";
  const needsSoundTruckConfig = scheduledPoint?.operationCategory === "sound_car" || /carro.*som|som.*carro/.test(scheduledServiceName);
  const needsFlyerConfig = scheduledPoint?.operationCategory === "leafleting" || /panflet|folder|flyer/.test(scheduledServiceName);
  const availableDistributionCities = (references.data?.cities ?? []).filter(({ city }) => !cityDistributions.some(item => Number(item.cityId) === city.id));
  const selectedSupplierId = Number(pointForm.supplierId || 0);
  const availableServiceTypes = (references.data?.serviceTypes ?? []).filter(type => !selectedSupplierId || (references.data?.supplierServiceTypes ?? []).some(link => link.supplierId === selectedSupplierId && link.serviceTypeId === type.id));
  const eligibleSupplierIds = new Set((references.data?.supplierMediaTypes ?? []).filter(link => (references.data?.mediaTypes ?? []).some(type => type.id === link.mediaTypeId && type.operationCategory === pointForm.operationCategory) && (!pointForm.mediaTypeId || link.mediaTypeId === Number(pointForm.mediaTypeId))).map(link => link.supplierId));
  const eligibleSuppliers = (references.data?.suppliers ?? []).filter(supplier => eligibleSupplierIds.has(supplier.id));
  const availableMediaTypes = (references.data?.mediaTypes ?? []).filter(type => type.operationCategory === pointForm.operationCategory && type.parentMediaTypeId !== null && (!selectedSupplierId || (references.data?.supplierMediaTypes ?? []).some(link => link.supplierId === selectedSupplierId && link.mediaTypeId === type.id)));
  const availableMediaVariations = (references.data?.mediaTypes ?? []).filter(type => type.operationCategory === pointForm.operationCategory && type.parentMediaTypeId === Number(pointForm.mediaTypeId));
  const addDistribution = () => { if (!distributionDraft.cityId || !distributionDraft.quantity) return; setCityDistributions(current => [...current, distributionDraft]); setDistributionDraft({ cityId: "", quantity: "", notes: "" }); };

  if (routeMediaPointId) return initialCategory === "graphics" || !initialCategory ? <UrbanPointDetails mediaPointId={routeMediaPointId} /> : <MediaDetailPage mediaPointId={routeMediaPointId} />;

  return <div className="mx-auto max-w-[1480px] space-y-6">
    <header className="flex flex-col gap-5 border-b border-border pb-6 lg:flex-row lg:items-end lg:justify-between"><div className="flex gap-4"><span className="grid h-12 w-12 shrink-0 place-items-center rounded-2xl bg-primary text-white shadow-sm"><RadioTower className="h-5 w-5" /></span><div><p className="text-[11px] font-semibold uppercase tracking-[0.14em] text-primary">Operação de mídia</p><h1 className="mt-1 font-display text-3xl font-semibold tracking-tight text-foreground">{categoryMeta?.title ?? (initialChannel === "external" ? "Mídias externas" : "Mídias e campanhas")}</h1><p className="mt-2 max-w-3xl text-sm leading-6 text-muted-foreground">{categoryMeta?.description ?? (initialChannel === "external" ? "Controle carros de som, panfletagem e outras ativações externas com contratação, vigência, agenda, comprovações e histórico." : "Controle mídia tradicional e externa, contratação, vigência, agenda, comprovações e histórico por ponto de cobertura.")}</p></div></div><div className="flex flex-wrap gap-2">{initialCategory === "graphics" && <Button type="button" variant="outline" onClick={() => setShowFilters(value => !value)} className="h-10 rounded-xl border-border px-4 text-xs font-semibold"><SlidersHorizontal className="mr-1.5 h-4 w-4" />Filtros</Button>}{canWrite && <Button onClick={() => { setPointForm({ ...emptyPoint, operationCategory: initialCategory ?? "graphics" }); setShowPointForm(true); }} className="h-10 rounded-xl bg-primary px-4 text-xs font-semibold hover:bg-primary/90"><Plus className="mr-1.5 h-4 w-4" />{initialCategory === "graphics" ? "Novo ponto de mídia urbana" : "Novo ponto de mídia"}</Button>}</div></header>

    <section className="rounded-2xl border border-border bg-card p-4 shadow-sm"><div className="flex flex-col gap-3 xl:flex-row xl:items-end"><div className="flex items-center gap-2 pb-1 text-sm font-semibold text-foreground"><SlidersHorizontal className="h-4 w-4 text-primary" />Filtros</div><div className="grid flex-1 gap-3 sm:grid-cols-2 lg:grid-cols-5"><SelectField label="Regional" value={filters.regionalId} onChange={event => setFilters({ ...filters, regionalId: event.target.value, cityId: "" })}><option value="">Todas</option>{references.data?.regionals.map(regional => <option key={regional.id} value={regional.id}>{regional.name}</option>)}</SelectField><SelectField label="Cidade" value={filters.cityId} onChange={event => setFilters({ ...filters, cityId: event.target.value })}><option value="">Todas</option>{references.data?.cities.filter(item => !filters.regionalId || item.city.regionalId === Number(filters.regionalId)).map(({ city, regionalName }) => <option key={city.id} value={city.id}>{city.name} · {regionalName}</option>)}</SelectField>{!initialCategory && <SelectField label="Canal" value={filters.channelKind} onChange={event => setFilters({ ...filters, channelKind: event.target.value })}><option value="">Todos</option><option value="standard">Mídia</option><option value="external">Mídia externa</option></SelectField>}<SelectField label="Situação" value={filters.status} onChange={event => setFilters({ ...filters, status: event.target.value })}><option value="">Todas</option><option value="active">Ativa</option><option value="scheduled">Agendada</option><option value="completed">Encerrada</option><option value="cancelled">Cancelada</option></SelectField><SelectField label="Modalidade" value={filters.partnershipType} onChange={event => setFilters({ ...filters, partnershipType: event.target.value })}><option value="">Todas</option><option value="paid">Pago</option><option value="barter">Permuta</option><option value="mixed">Misto</option></SelectField></div><Button variant="outline" className="h-10 border-border" onClick={resetFilters}>Limpar</Button></div></section>

    {(initialCategory === "audio_video" || initialCategory === "sound_car" || initialCategory === "influencers") && <MediaSpecializedOperationsPanel category={initialCategory} canWrite={canWrite} />}

    <section className="overflow-hidden rounded-2xl border border-border bg-card shadow-sm"><div className="flex flex-col gap-3 border-b border-border px-5 py-4 sm:flex-row sm:items-center sm:justify-between"><div><p className="font-display text-lg font-semibold text-foreground">Lista de mídias</p><p className="mt-0.5 text-xs text-muted-foreground">Clique em um item para abrir os dados completos, ciclos e evidências.</p></div><Badge variant="outline" className="w-fit border-border bg-secondary text-xs text-foreground">{points.data?.length ?? 0} pontos encontrados</Badge></div>{points.isLoading ? <div className="p-10 text-center text-sm text-muted-foreground">Carregando mídias...</div> : points.data?.length ? <div className="divide-y divide-border">{points.data.map(point => { const focusCampaign = point.activeCampaign ?? point.nextCampaign; return <article key={point.id} className="group grid gap-4 px-5 py-4 transition hover:bg-secondary/35 lg:grid-cols-[minmax(0,1.5fr)_minmax(230px,.8fr)_auto]"><button type="button" onClick={() => setDetailPointId(point.id)} className="min-w-0 text-left"><div className="flex flex-wrap items-center gap-2">{point.coverImageUrl ? <img src={point.coverImageUrl} alt={`Identificação de ${point.name}`} className="h-11 w-11 rounded-lg border border-border bg-secondary object-cover" /> : <span className={`grid h-11 w-11 place-items-center rounded-lg ${point.channelKind === "external" ? "bg-orange-500/10 text-orange-600" : "bg-primary/10 text-primary"}`}>{point.channelKind === "external" ? <Truck className="h-4 w-4" /> : <Megaphone className="h-4 w-4" />}</span>}<div><p className="font-semibold text-foreground group-hover:text-primary">{point.name}</p><p className="mt-0.5 text-xs text-muted-foreground">{point.channelKind === "external" ? "Mídia externa" : "Mídia"} · {point.mediaTypeName}{point.serviceTypeName ? ` · ${point.serviceTypeName}` : ""}</p></div></div><p className="mt-3 flex items-center gap-1 text-xs text-muted-foreground"><Building2 className="h-3.5 w-3.5" />{point.supplierName}</p><p className="mt-1 flex items-center gap-1 text-xs text-muted-foreground"><MapPin className="h-3.5 w-3.5" />{point.cityName} · {point.regionalName}</p></button><button type="button" onClick={() => setDetailPointId(point.id)} className="rounded-xl border border-border bg-background p-3 text-left transition hover:border-primary/40"><div className="flex items-center justify-between gap-2"><span className="text-[11px] font-semibold uppercase tracking-[.12em] text-muted-foreground">Campanha atual</span><ChevronRight className="h-4 w-4 text-muted-foreground" /></div>{focusCampaign ? <><p className="mt-2 truncate text-sm font-semibold text-foreground">{focusCampaign.name}</p><div className="mt-2 flex flex-wrap gap-1.5"><Badge className="border-0 bg-primary/10 text-[10px] text-primary">{campaignStatusLabel[focusCampaign.status] ?? focusCampaign.status}</Badge><Badge className="border-0 bg-secondary text-[10px] text-foreground">{partnershipLabel[focusCampaign.partnershipType as PartnershipType]}</Badge></div><p className="mt-2 text-xs text-muted-foreground">{new Date(`${focusCampaign.startsOn}T12:00:00`).toLocaleDateString("pt-BR")} — {new Date(`${focusCampaign.endsOn}T12:00:00`).toLocaleDateString("pt-BR")}</p><p className="mt-2 text-[11px] text-muted-foreground">Previsto: <strong className="text-foreground">{Number(focusCampaign.finance.estimatedAmount).toLocaleString("pt-BR", { style: "currency", currency: "BRL" })}</strong> · Pago: <strong className="text-foreground">{Number(focusCampaign.finance.paidAmount).toLocaleString("pt-BR", { style: "currency", currency: "BRL" })}</strong></p><p className="mt-1 text-[11px] text-muted-foreground">Saldo: <strong className={focusCampaign.finance.remainingAmount > 0 ? "text-orange-600" : "text-primary"}>{Number(focusCampaign.finance.remainingAmount).toLocaleString("pt-BR", { style: "currency", currency: "BRL" })}</strong></p></> : <p className="mt-2 text-sm text-muted-foreground">Sem campanha programada</p>}</button><div className="flex items-center gap-2 lg:justify-end"><Button variant="outline" size="sm" onClick={() => setDetailPointId(point.id)} className="h-9 rounded-lg border-border text-xs"><FileImage className="mr-1.5 h-3.5 w-3.5" />Detalhes</Button>{canWrite && <Button size="sm" onClick={() => openSchedule(point.id)} className="h-9 rounded-lg bg-primary text-xs hover:bg-primary/90"><CalendarClock className="mr-1.5 h-3.5 w-3.5" />{point.activeCampaign ? "Agendar" : "Nova campanha"}</Button>}</div></article>; })}</div> : <div className="p-12 text-center"><RadioTower className="mx-auto h-7 w-7 text-muted-foreground" /><p className="mt-3 text-sm font-semibold text-foreground">Nenhum ponto para estes filtros</p><p className="mt-1 text-xs text-muted-foreground">Ajuste os filtros ou registre uma nova mídia para iniciar o acompanhamento.</p></div>}</section>

    <Dialog open={detailPointId !== null} onOpenChange={open => { if (!open) setDetailPointId(null); }}><DialogContent className="max-h-[92vh] max-w-6xl overflow-y-auto"><DialogHeader><DialogTitle>{pointDetails.data?.name ?? "Detalhes da mídia"}</DialogTitle><DialogDescription>Fornecedor, cobertura, campanhas, contratação, histórico e comprovações do ponto selecionado.</DialogDescription></DialogHeader>{pointDetails.isLoading ? <div className="grid h-48 place-items-center text-sm text-muted-foreground">Carregando detalhes...</div> : pointDetails.data && <div className="grid gap-5 lg:grid-cols-[.8fr_1.2fr]"><aside className="space-y-4"><article className="rounded-xl bg-secondary p-4"><div className="flex items-center gap-2 text-sm font-semibold text-foreground"><Building2 className="h-4 w-4 text-primary" />Cobertura e fornecedor</div><dl className="mt-4 space-y-3 text-sm"><div><dt className="text-xs text-muted-foreground">Fornecedor</dt><dd className="font-medium text-foreground">{pointDetails.data.supplierName}</dd></div><div><dt className="text-xs text-muted-foreground">Território</dt><dd className="font-medium text-foreground">{pointDetails.data.cityName} · {pointDetails.data.regionalName}</dd></div><div><dt className="text-xs text-muted-foreground">Tipo de mídia</dt><dd className="font-medium text-foreground">{pointDetails.data.mediaTypeName}{pointDetails.data.serviceTypeName ? ` · ${pointDetails.data.serviceTypeName}` : ""}</dd></div><div><dt className="text-xs text-muted-foreground">Localização</dt><dd className="font-medium text-foreground">{pointDetails.data.address || "Não informada"}</dd></div></dl></article><article className="rounded-xl border border-border p-4"><div className="flex items-center gap-2 text-sm font-semibold text-foreground"><History className="h-4 w-4 text-primary" />Histórico</div><div className="mt-3 space-y-3">{(pointDetails.data.history ?? []).length ? (pointDetails.data.history ?? []).map(entry => <div key={`${entry.scope}-${entry.id}`} className="border-l-2 border-primary/30 pl-3"><p className="text-xs font-medium text-foreground">{entry.action === "schedule" ? "Campanha agendada" : entry.action === "reschedule" ? "Campanha reagendada" : entry.action === "create" ? "Registro criado" : "Atualização registrada"}</p><p className="mt-0.5 text-[11px] text-muted-foreground">{new Date(entry.occurredAt).toLocaleString("pt-BR")}</p></div>) : <p className="text-xs text-muted-foreground">Ainda não há alterações registradas.</p>}</div></article></aside><section className="overflow-hidden rounded-xl border border-border"><div className="flex items-center justify-between gap-3 border-b border-border px-4 py-3"><div><p className="text-sm font-semibold text-foreground">Ciclos e comprovações</p><p className="mt-0.5 text-xs text-muted-foreground">Toda programação e alteração permanece no histórico deste ponto.</p></div>{canWrite && <Button size="sm" onClick={() => openSchedule(pointDetails.data!.id)} className="bg-primary text-xs hover:bg-primary/90"><Plus className="mr-1.5 h-3.5 w-3.5" />Agendar</Button>}</div><div className="divide-y divide-border">{(pointDetails.data.campaigns ?? []).length ? (pointDetails.data.campaigns ?? []).map(campaign => <article key={campaign.id} className="p-4"><div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between"><div><div className="flex flex-wrap items-center gap-2"><p className="font-semibold text-foreground">{campaign.name}</p><Badge className="border-0 bg-secondary text-[10px] text-foreground">{campaignStatusLabel[campaign.status] ?? campaign.status}</Badge><Badge className="border-0 bg-primary/10 text-[10px] text-primary">{partnershipLabel[campaign.partnershipType as PartnershipType]}</Badge></div><p className="mt-1 text-xs text-muted-foreground">{new Date(`${campaign.startsOn}T12:00:00`).toLocaleDateString("pt-BR")} até {new Date(`${campaign.endsOn}T12:00:00`).toLocaleDateString("pt-BR")} · {Number(campaign.estimatedCost).toLocaleString("pt-BR", { style: "currency", currency: "BRL" })}</p>{campaign.campaignDetails && <p className="mt-2 text-xs leading-5 text-muted-foreground">{campaign.campaignDetails}</p>}{campaign.notes && <p className="mt-1 text-xs leading-5 text-muted-foreground">{campaign.notes}</p>}</div>{canWrite && ["active", "scheduled"].includes(campaign.status) && <Button variant="outline" size="sm" className="h-8 border-border text-xs" onClick={() => openReschedule(campaign)}><RotateCcw className="mr-1.5 h-3.5 w-3.5" />Reagendar</Button>}</div><div className="mt-3 flex flex-wrap gap-2">{campaign.evidences.map(evidence => <a key={evidence.id} href={evidence.url} target="_blank" rel="noreferrer" className="inline-flex items-center gap-1 rounded-md bg-secondary px-2 py-1 text-[11px] font-medium text-foreground hover:bg-primary/10"><ExternalLink className="h-3 w-3" />{evidence.originalName}</a>)}</div><div className="mt-3"><EvidenceUpload entityType="media_campaign" entityId={campaign.id} regionalId={pointDetails.data!.regionalId} canWrite={canWrite} /></div></article>) : <p className="p-5 text-sm text-muted-foreground">Nenhuma campanha registrada para este ponto.</p>}</div></section></div>}</DialogContent></Dialog>

    <Dialog open={showPointForm} onOpenChange={setShowPointForm}><DialogContent className="max-h-[92vh] max-w-3xl overflow-y-auto"><DialogHeader><DialogTitle>{pointForm.operationCategory === "graphics" ? "Novo ponto de mídia urbana" : "Novo ponto de mídia"}</DialogTitle><DialogDescription>Registre o local físico. A variação, o contrato e as veiculações serão definidos na ficha do ponto.</DialogDescription></DialogHeader><form onSubmit={submitPoint} className="grid gap-4 pt-2 md:grid-cols-2"><SearchableMultiSelect id="media-city" label="Cidade do ponto" options={(references.data?.cities ?? []).map(({ city, regionalName }) => ({ id: city.id, label: city.name, description: regionalName }))} values={pointForm.cityId ? [Number(pointForm.cityId)] : []} onChange={values => setPointForm({ ...pointForm, cityId: values[0] ? String(values[0]) : "", supplierId: "", serviceTypeId: "", mediaTypeId: "" })} maxSelections={1} placeholder="Selecionar cidade" emptyMessage="Nenhuma cidade disponível" /><SearchableMultiSelect id="media-supplier" label="Fornecedor" disabled={!pointForm.cityId} options={eligibleSuppliers.map(supplier => ({ id: supplier.id, label: supplier.displayName, description: supplier.mainService || "Fornecedor de mídia" }))} values={pointForm.supplierId ? [Number(pointForm.supplierId)] : []} onChange={values => setPointForm({ ...pointForm, supplierId: values[0] ? String(values[0]) : "", serviceTypeId: "", mediaTypeId: "" })} maxSelections={1} placeholder={pointForm.cityId ? "Selecionar fornecedor" : "Selecione a cidade primeiro"} emptyMessage="Nenhum fornecedor habilitado nesta categoria" /><SearchableMultiSelect id="media-subtype" label="Tipo de mídia" disabled={!selectedSupplierId} options={availableMediaTypes.map(type => ({ id: type.id, label: type.name, description: "Disponível neste fornecedor" }))} values={pointForm.mediaTypeId ? [Number(pointForm.mediaTypeId)] : []} onChange={values => setPointForm({ ...pointForm, mediaTypeId: values[0] ? String(values[0]) : "" })} maxSelections={1} placeholder={selectedSupplierId ? "Selecionar tipo" : "Selecione o fornecedor primeiro"} emptyMessage="Nenhum tipo vinculado ao fornecedor" /><label className="space-y-1.5"><Label htmlFor="media-name">Nome do ponto</Label><Input id="media-name" required value={pointForm.name} onChange={event => setPointForm({ ...pointForm, name: event.target.value })} placeholder="Ex.: Outdoor Av. Central" /></label><SearchableMultiSelect id="media-service" label="Serviço do fornecedor" disabled={!selectedSupplierId} options={availableServiceTypes.map(type => ({ id: type.id, label: type.name }))} values={pointForm.serviceTypeId ? [Number(pointForm.serviceTypeId)] : []} onChange={values => setPointForm({ ...pointForm, serviceTypeId: values[0] ? String(values[0]) : "" })} maxSelections={1} placeholder="Selecionar serviço (opcional)" emptyMessage="Nenhum serviço configurado" /><label className="space-y-1.5 md:col-span-2"><Label htmlFor="media-address">Localização ou rota de referência</Label><Input id="media-address" value={pointForm.address} onChange={event => setPointForm({ ...pointForm, address: event.target.value })} placeholder="Endereço, fachada, sentido da via ou rota de referência" /></label><label className="space-y-1.5 md:col-span-2"><Label htmlFor="media-coordinates">Latitude e longitude</Label><Input id="media-coordinates" value={pointForm.coordinates} onChange={event => setPointForm({ ...pointForm, coordinates: event.target.value })} placeholder="Ex.: -18.95677454094437, -46.99206057116672" /><p className="text-xs text-muted-foreground">Cole as coordenadas do Google em uma única linha. O ponto será disponibilizado no mapa de Indicadores.</p></label><div className="flex justify-end md:col-span-2"><Button type="submit" disabled={createPoint.isPending || !selectedSupplierId || !pointForm.mediaTypeId || !pointForm.cityId} className="bg-primary hover:bg-primary/90">{createPoint.isPending ? <RefreshCw className="mr-2 h-4 w-4 animate-spin" /> : null}Salvar ponto</Button></div></form></DialogContent></Dialog>

    <Dialog open={campaignPointId !== null || rescheduleCampaignId !== null} onOpenChange={open => { if (!open) { setCampaignPointId(null); setRescheduleCampaignId(null); setCityDistributions([]); } }}>
      <DialogContent className="max-h-[92vh] max-w-4xl overflow-y-auto">
        <DialogHeader><DialogTitle>{rescheduleCampaignId ? "Reagendar mídia" : "Agendar campanha de mídia"}</DialogTitle><DialogDescription>{rescheduleCampaignId ? "Registre a nova vigência e os detalhes da substituição. O ciclo anterior será preservado no histórico." : "Defina a campanha e seus parâmetros operacionais para acompanhamento completo."}</DialogDescription></DialogHeader>
	        <form onSubmit={submitCampaign} className="grid gap-4 pt-2 md:grid-cols-2">
	          <label className="space-y-1.5 md:col-span-2"><Label htmlFor="campaign-name">Nome da campanha</Label><Input id="campaign-name" required value={campaignForm.name} onChange={event => setCampaignForm({ ...campaignForm, name: event.target.value })} placeholder="Ex.: Campanha de setembro" /></label>
	          {!rescheduleCampaignId && <div className="md:col-span-2"><SearchableMultiSelect id="media-trade-campaign" label="Campanha comercial" options={(tradeCampaigns.data ?? []).map(campaign => ({ id: campaign.id, label: campaign.name, description: `${campaign.status === "active" ? "Ativa" : "Planejada"}${campaign.regionalName ? ` · ${campaign.regionalName}` : ""}` }))} values={campaignForm.tradeCampaignId ? [Number(campaignForm.tradeCampaignId)] : []} onChange={values => setCampaignForm({ ...campaignForm, tradeCampaignId: values[0] ? String(values[0]) : "" })} maxSelections={1} placeholder="Vincular a uma campanha (opcional)" emptyMessage="Nenhuma campanha comercial disponível" /></div>}
          <label className="space-y-1.5"><Label htmlFor="campaign-start">Início</Label><Input id="campaign-start" required type="date" value={campaignForm.startsOn} onChange={event => setCampaignForm({ ...campaignForm, startsOn: event.target.value })} /></label>
          <label className="space-y-1.5"><Label htmlFor="campaign-end">Término</Label><Input id="campaign-end" required type="date" value={campaignForm.endsOn} onChange={event => setCampaignForm({ ...campaignForm, endsOn: event.target.value })} /></label>
          <SearchableMultiSelect id="media-partnership" label="Modalidade de contratação" options={[{ id: 1, label: "Pago" }, { id: 2, label: "Permuta" }, { id: 3, label: "Misto" }]} values={[({ paid: 1, barter: 2, mixed: 3 } as const)[campaignForm.partnershipType]]} onChange={values => setCampaignForm({ ...campaignForm, partnershipType: ({ 1: "paid", 2: "barter", 3: "mixed" } as const)[values[0] as 1 | 2 | 3] ?? "paid" })} maxSelections={1} placeholder="Selecionar modalidade" emptyMessage="Nenhuma modalidade disponível" />
          <label className="space-y-1.5"><Label htmlFor="campaign-cost">Investimento previsto</Label><Input id="campaign-cost" required type="number" min="0" step="0.01" value={campaignForm.estimatedCost} onChange={event => setCampaignForm({ ...campaignForm, estimatedCost: event.target.value })} placeholder="0,00" /></label>
          <label className="space-y-1.5 md:col-span-2"><Label htmlFor="campaign-details">Detalhes da campanha</Label><Textarea id="campaign-details" value={campaignForm.campaignDetails} onChange={event => setCampaignForm({ ...campaignForm, campaignDetails: event.target.value })} placeholder="Peças, entregas, contrapartidas, público, rota ou outros detalhes operacionais" /></label>
	          {!rescheduleCampaignId && needsAudioVideoConfig && <section className="grid gap-3 rounded-xl border border-primary/20 bg-primary/5 p-4 md:col-span-2"><div><p className="font-semibold text-foreground">Configuração de Áudio e Vídeo</p><p className="text-xs text-muted-foreground">Registre o funcionamento do veículo, a grade de veiculação e o spot ativo neste ciclo.</p></div><SearchableMultiSelect id="media-active-spot" label="Spot ativo" options={(specializedData.data?.spots ?? []).filter(spot => spot.active).map(spot => ({ id: spot.id, label: spot.name, description: spot.notes || "Spot disponível" }))} values={campaignForm.activeSpotId ? [Number(campaignForm.activeSpotId)] : []} onChange={values => setCampaignForm({ ...campaignForm, activeSpotId: values[0] ? String(values[0]) : "" })} maxSelections={1} placeholder="Selecionar spot (opcional)" emptyMessage="Cadastre um spot ativo no painel acima" /><label className="space-y-1.5"><Label>Como o veículo opera</Label><Textarea value={campaignForm.vehicleOperation} onChange={event => setCampaignForm({ ...campaignForm, vehicleOperation: event.target.value })} placeholder="Ex.: programa, praça atendida, formato de inserção e regras do veículo" /></label><label className="space-y-1.5"><Label>Horários de veiculação</Label><Textarea value={campaignForm.airingSchedule} onChange={event => setCampaignForm({ ...campaignForm, airingSchedule: event.target.value })} placeholder="Ex.: seg–sex, 07h15, 12h30 e 18h45; 3 inserções diárias" /></label></section>}
          {!rescheduleCampaignId && needsSoundTruckConfig && <section className="grid gap-3 rounded-xl border border-orange-200 bg-orange-50/70 p-4 md:col-span-2 dark:border-orange-900/60 dark:bg-orange-950/20"><div><p className="font-semibold text-foreground">Configuração de carro de som</p><p className="text-xs text-muted-foreground">Defina a rota, os dias de circulação, a diária e os áudios de campanha.</p></div><div className="grid gap-3 md:grid-cols-2"><label className="space-y-1.5"><Label>Quantidade de dias</Label><Input type="number" min="1" value={campaignForm.circulationDays} onChange={event => setCampaignForm({ ...campaignForm, circulationDays: event.target.value })} /></label><label className="space-y-1.5"><Label>Valor por diária</Label><Input type="number" min="0" step="0.01" value={campaignForm.dailyRate} onChange={event => setCampaignForm({ ...campaignForm, dailyRate: event.target.value })} /></label></div><label className="space-y-1.5"><Label>Rota e horários diários</Label><Textarea value={campaignForm.dailyRoute} onChange={event => setCampaignForm({ ...campaignForm, dailyRoute: event.target.value })} placeholder="Cidades, bairros, horários e período de circulação" /></label><label className="space-y-1.5"><Label>Briefing dos áudios</Label><Textarea value={campaignForm.audioBrief} onChange={event => setCampaignForm({ ...campaignForm, audioBrief: event.target.value })} placeholder="Versão, locução, CTA, vigência e instruções. Após salvar, anexe os áudios na campanha." /></label></section>}
          {!rescheduleCampaignId && needsFlyerConfig && <section className="grid gap-3 rounded-xl border border-sky-200 bg-sky-50/70 p-4 md:col-span-2 dark:border-sky-900/60 dark:bg-sky-950/20"><div><p className="font-semibold text-foreground">Configuração de panfletagem</p><p className="text-xs text-muted-foreground">Distribua o material por cidade para acompanhar a execução territorial.</p></div><div className="grid gap-3 md:grid-cols-3"><label className="space-y-1.5"><Label>Formato do material</Label><Input value={campaignForm.materialFormat} onChange={event => setCampaignForm({ ...campaignForm, materialFormat: event.target.value })} placeholder="Ex.: A5 frente e verso" /></label><label className="space-y-1.5"><Label>Quantidade total</Label><Input type="number" min="1" value={campaignForm.materialQuantity} onChange={event => setCampaignForm({ ...campaignForm, materialQuantity: event.target.value })} /></label><label className="space-y-1.5"><Label>Prazo (dias)</Label><Input type="number" min="0" value={campaignForm.deadlineDays} onChange={event => setCampaignForm({ ...campaignForm, deadlineDays: event.target.value })} /></label></div><label className="space-y-1.5"><Label>Instruções de distribuição</Label><Textarea value={campaignForm.deliveryInstructions} onChange={event => setCampaignForm({ ...campaignForm, deliveryInstructions: event.target.value })} placeholder="Público, locais, equipe, abordagem e critérios de entrega" /></label><div className="grid gap-3 rounded-lg border border-border bg-background/70 p-3 md:grid-cols-[1.4fr_.8fr_1.2fr_auto]"><SelectField label="Cidade" value={distributionDraft.cityId} onChange={event => setDistributionDraft({ ...distributionDraft, cityId: event.target.value })}><option value="">Selecionar</option>{availableDistributionCities.map(({ city, regionalName }) => <option key={city.id} value={city.id}>{city.name} · {regionalName}</option>)}</SelectField><label className="space-y-1.5"><Label>Quantidade</Label><Input type="number" min="1" value={distributionDraft.quantity} onChange={event => setDistributionDraft({ ...distributionDraft, quantity: event.target.value })} /></label><label className="space-y-1.5"><Label>Observação</Label><Input value={distributionDraft.notes} onChange={event => setDistributionDraft({ ...distributionDraft, notes: event.target.value })} placeholder="Ex.: centro e bairros" /></label><Button type="button" className="self-end" variant="outline" onClick={addDistribution} disabled={!distributionDraft.cityId || !distributionDraft.quantity}>Adicionar</Button></div>{cityDistributions.length ? <div className="space-y-2">{cityDistributions.map((distribution, index) => <div key={distribution.cityId} className="flex items-center justify-between rounded-lg border border-border bg-background px-3 py-2 text-sm"><span>{references.data?.cities.find(item => item.city.id === Number(distribution.cityId))?.city.name ?? "Cidade"}: <strong>{distribution.quantity}</strong> unidades{distribution.notes ? ` · ${distribution.notes}` : ""}</span><Button type="button" size="sm" variant="ghost" className="text-destructive" onClick={() => setCityDistributions(current => current.filter((_, itemIndex) => itemIndex !== index))}>Remover</Button></div>)}</div> : null}</section>}
          {rescheduleCampaignId && <label className="space-y-1.5 md:col-span-2"><Label htmlFor="campaign-reason">Motivo do reagendamento</Label><Textarea id="campaign-reason" value={campaignForm.rescheduleReason} onChange={event => setCampaignForm({ ...campaignForm, rescheduleReason: event.target.value })} placeholder="Ex.: renovação negociada com nova peça e prazo" /></label>}
          <label className="space-y-1.5 md:col-span-2"><Label htmlFor="campaign-notes">Observações internas</Label><Textarea id="campaign-notes" value={campaignForm.notes} onChange={event => setCampaignForm({ ...campaignForm, notes: event.target.value })} placeholder="Informações de acompanhamento interno" /></label>
          <div className="flex justify-end gap-2 md:col-span-2"><Button type="button" variant="outline" onClick={() => { setCampaignPointId(null); setRescheduleCampaignId(null); }}>Cancelar</Button><Button type="submit" disabled={createConfiguredCampaign.isPending || renewCampaign.isPending} className="bg-primary hover:bg-primary/90">{(createConfiguredCampaign.isPending || renewCampaign.isPending) && <RefreshCw className="mr-2 h-4 w-4 animate-spin" />}{rescheduleCampaignId ? "Confirmar reagendamento" : "Confirmar programação"}</Button></div>
        </form>
      </DialogContent>
    </Dialog>
    {canWrite && (() => {
      const campaignsForDebrief = (points.data ?? []).flatMap(point => (point.campaigns ?? []).map(campaign => ({ campaign, pointName: point.name }))).filter(({ campaign }) => campaign.status !== "scheduled");
      return campaignsForDebrief.length ? <section className="rounded-2xl border border-border bg-card p-5 shadow-sm"><div className="flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between"><div><p className="font-display text-lg font-semibold text-foreground">Pós-operação de mídia</p><p className="mt-1 text-sm text-muted-foreground">Registre a nota, o resultado e o debriefing de campanhas concluídas, canceladas ou em andamento.</p></div></div><div className="mt-4 grid gap-3 lg:grid-cols-2">{campaignsForDebrief.map(({ campaign, pointName }) => <article key={campaign.id} className="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-border bg-background p-3"><div><p className="text-sm font-semibold text-foreground">{campaign.name}</p><p className="mt-1 text-xs text-muted-foreground">{pointName} · {campaign.rating ? `Nota ${campaign.rating}/5` : "Sem avaliação"}</p></div><Button type="button" size="sm" variant="outline" className="border-border text-xs" onClick={() => openDebrief(campaign)}>{campaign.feedback ? "Editar debriefing" : "Registrar debriefing"}</Button></article>)}</div></section> : null;
    })()}

    <Dialog open={debriefCampaignId !== null} onOpenChange={open => { if (!open) setDebriefCampaignId(null); }}><DialogContent className="max-w-xl"><DialogHeader><DialogTitle>Debriefing da mídia</DialogTitle><DialogDescription>Registre a avaliação e os aprendizados do ciclo de mídia para comparação futura.</DialogDescription></DialogHeader><form onSubmit={submitDebrief} className="space-y-4 pt-2"><SelectField label="Nota da campanha" required value={debriefForm.rating} onChange={event => setDebriefForm({ ...debriefForm, rating: event.target.value })}><option value="">Selecionar</option><option value="1">1 · Muito abaixo do esperado</option><option value="2">2 · Abaixo do esperado</option><option value="3">3 · Dentro do esperado</option><option value="4">4 · Bom resultado</option><option value="5">5 · Excelente resultado</option></SelectField><label className="flex items-center gap-3 rounded-lg border border-border bg-secondary/40 p-3 text-sm text-foreground"><input type="checkbox" checked={debriefForm.resultAchieved} onChange={event => setDebriefForm({ ...debriefForm, resultAchieved: event.target.checked })} className="h-4 w-4 accent-primary" />Resultado previsto atingido</label><label className="block space-y-1.5"><Label htmlFor="media-feedback">Debriefing</Label><Textarea id="media-feedback" required minLength={3} value={debriefForm.feedback} onChange={event => setDebriefForm({ ...debriefForm, feedback: event.target.value })} placeholder="Resultados, aprendizados, ajustes sugeridos e recomendação para próximos ciclos" /></label><div className="flex justify-end gap-2"><Button type="button" variant="outline" onClick={() => setDebriefCampaignId(null)}>Cancelar</Button><Button type="submit" disabled={saveDebrief.isPending} className="bg-primary hover:bg-primary/90">{saveDebrief.isPending && <RefreshCw className="mr-2 h-4 w-4 animate-spin" />}Salvar debriefing</Button></div></form></DialogContent></Dialog>
  </div>;
}
